```metal
#include <metal_stdlib>
using namespace metal;

// Define the Gaussian blur kernel size and sigma
constant int kernelSize = 5;
constant float sigma = 2.0;

// Calculate the Gaussian weight
float gaussian(float x, float sigma) {
    return exp(-(x*x) / (2*sigma*sigma)) / (sigma * sqrt(2*M_PI));
}

// Define the compute kernel function
kernel void gaussian_blur(texture2d<float, access::read> inputTexture [[texture(0)]],
                          texture2d<float, access::write> outputTexture [[texture(1)]],
                          uint2 gid [[thread_position_in_grid]]) {
    // Calculate the texture size
    int2 textureSize = int2(inputTexture.get_width(), inputTexture.get_height());

    // Initialize the color and weight sum
    float4 color = float4(0.0);
    float weightSum = 0.0;

    // Calculate the Gaussian weights
    float weights[kernelSize];
    for (int i = 0; i < kernelSize; ++i) {
        weights[i] = gaussian(i - kernelSize / 2, sigma);
        weightSum += weights[i];
    }

    // Apply the Gaussian blur
    for (int y = -kernelSize / 2; y <= kernelSize / 2; ++y) {
        for (int x = -kernelSize / 2; x <= kernelSize / 2; ++x) {
            // Calculate the sample position
            int2 samplePos = int2(gid) + int2(x, y);

            // Clamp the position to the texture bounds
            samplePos = clamp(samplePos, int2(0), textureSize - int2(1));

            // Read the sample color
            float4 sampleColor = inputTexture.read(uint2(samplePos));

            // Accumulate the color using the Gaussian weight
            color += sampleColor * weights[x + kernelSize / 2] * weights[y + kernelSize / 2];
        }
    }

    // Normalize the color by the weight sum
    color /= weightSum;

    // Write the blurred color to the output texture
    outputTexture.write(color, gid);
}
```

This kernel function reads from an input texture, applies a Gaussian blur using a specified kernel size and sigma value, and writes the result to an output texture. The Gaussian weights are calculated using the Gaussian function, and the blur is applied by taking a weighted average of the surrounding pixels.

