            // End of file
            printf("End of file reached.\n");
            break;
        } else {
            // Null-terminate and print the buffer
            buffer[bytes_read] = '\0';
            printf("Read %zd bytes: %s\n", bytes_read, buffer);
        }
    }

    return 0;
}
