Here's a simple example of how to create a pull-based stream:

```javascript
const { Readable } = require('stream');

class MyReadableStream extends Readable {
  constructor(options) {
    super(options);
    this.data = ['some', 'data', 'to', 'stream', null]; // null indicates the end of the stream
  }

  _read(size) {
    let chunk;
    while (null !== (chunk = this.data.shift())) {
      if (!this.push(chunk)) {
        // When push returns false, stop pushing data until the next _read call
        break;
      }
    }
  }
}

const myStream = new MyReadableStream();

myStream.on('data', (chunk) => {
  console.log(`Received: ${chunk}`);
});

myStream.on('end', () => {
  console.log('No more data.');
});
```

In this example, the `MyReadableStream` class extends the `Readable` class. The `_read` method is implemented to "pull" data from a source (in this case, an array) and push it to the stream's consumer. The `null` value in the array signals the end of the stream.

