import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;

public class KubernetesLogsReader {

    private final HttpClient httpClient;
    private final String kubernetesApiUrl;
    private final String authToken;

    public KubernetesLogsReader(String kubernetesApiUrl, String authToken) {
        this.httpClient = HttpClient.newHttpClient();
        this.kubernetesApiUrl = kubernetesApiUrl;
        this.authToken = authToken;
    }

    public String getPodLogs(String namespace, String podName) throws Exception {
        URI uri = new URI(kubernetesApiUrl + "/api/v1/namespaces/" + namespace + "/pods/" + podName + "/log");
        HttpRequest request = HttpRequest.newBuilder(uri)
                .header("Authorization", "Bearer " + authToken)
                .GET()
                .build();

        HttpResponse<String> response = httpClient.send(request, HttpResponse.BodyHandlers.ofString());

        if (response.statusCode() == 200) {
            return response.body();
        } else {
            throw new RuntimeException("Failed to get pod logs: HTTP status " + response.statusCode());
