```typescript
class SimpleRNN {
  inputSize: number;
  hiddenSize: number;
  outputSize: number;
  weightsIH: number[][];
  weightsHO: number[][];
  hiddenState: number[];

  constructor(inputSize: number, hiddenSize: number, outputSize: number) {
    this.inputSize = inputSize;
    this.hiddenSize = hiddenSize;
    this.outputSize = outputSize;
    this.weightsIH = this.initWeights(hiddenSize, inputSize);
    this.weightsHO = this.initWeights(outputSize, hiddenSize);
    this.hiddenState = new Array(hiddenSize).fill(0);
  }

  initWeights(rows: number, cols: number): number[][] {
    let matrix = [];
    for (let i = 0; i < rows; i++) {
      matrix[i] = [];
      for (let j = 0; j < cols; j++) {
        matrix[i][j] = Math.random() * 2 - 1; // Random initialization
      }
    }
    return matrix;
  }

  forward(input: number[]): number[] {
    // Compute new hidden state
    let newHidden = this.hiddenState.map((_, i) =>
      this.weightsIH[i].reduce((acc, weight, j) => acc + weight * input[j], 0)
    );
    newHidden = newHidden.map(this.activation);

    // Compute output
    let output = this.weightsHO.map((weights) =>
      weights.reduce((acc, weight, i) => acc + weight * newHidden[i], 0)
    );

    this.hiddenState = newHidden; // Update hidden state
    return output;
  }

  activation(x: number): number {
    return Math.tanh(x); // Hyperbolic tangent activation
  }
}

// Example usage
