```typescript
class SimpleRNN {
    inputSize: number;
    hiddenSize: number;
    outputSize: number;
    hiddenState: number[];
    weightsIH: number[][];
    weightsHO: number[][];

    constructor(inputSize: number, hiddenSize: number, outputSize: number) {
        this.inputSize = inputSize;
        this.hiddenSize = hiddenSize;
        this.outputSize = outputSize;
        this.hiddenState = new Array(hiddenSize).fill(0);
        this.weightsIH = this.initWeights(hiddenSize, inputSize);
        this.weightsHO = this.initWeights(outputSize, hiddenSize);
    }

    initWeights(rows: number, columns: number): number[][] {
        let weights = [];
        for (let i = 0; i < rows; i++) {
            weights[i] = [];
            for (let j = 0; j < columns; j++) {
                weights[i][j] = Math.random() * 2 - 1; // Random weights between -1 and 1
            }
        }
        return weights;
    }

    forward(input: number[]): number[] {
        // Compute new hidden state
        let newHiddenState = this.hiddenState.map((_, i) => {
            return this.tanh(
                input.reduce((acc, inp, j) => acc + inp * this.weightsIH[i][j], 0) +
                this.hiddenState[i]
            );
        });

        // Compute output
        let output = newHiddenState.map((hidden, i) => {
            return this.tanh(
                this.weightsHO[i].reduce((acc, weight, j) => acc + weight * hidden, 0)
            );
        });

        this.hiddenState = newHiddenState; // Update hidden state
        return output;
    }

    tanh(x: number): number {
        return Math.tanh(x);
    }
}

// Example usage
const rnn = new SimpleRNN(3, 5, 2);
const input = [0.5, -0.1, 0.3];
const output = rnn.forward(input);
console.log(output);
```

