```csharp
public partial class SierpinskiTriangle : UserControl
{
    public SierpinskiTriangle()
    {
        InitializeComponent();
        DrawSierpinski(0, new Point(0, 0), new Point(100, 0), new Point(50, 50), 5);
    }

    private void DrawSierpinski(int depth, Point a, Point b, Point c, int maxDepth)
    {
        if (depth >= maxDepth)
        {
            // Draw the triangle using the Polygon element
            var polygon = new Polygon
            {
                Points = new PointCollection { a, b, c },
                Stroke = Brushes.Black,
                Fill = Brushes.Black
            };
            TriangleCanvas.Children.Add(polygon);
        }
        else
        {
            // Calculate midpoints
            var ab = Midpoint(a, b);
            var bc = Midpoint(b, c);
            var ca = Midpoint(c, a);

            // Recursively draw the three inner triangles
            DrawSierpinski(depth + 1, a, ab, ca, maxDepth);
            DrawSierpinski(depth + 1, ab, b, bc, maxDepth);
            DrawSierpinski(depth + 1, ca, bc, c, maxDepth);
        }
    }

    private Point Midpoint(Point p1, Point p2)
    {
        return new Point((p1.X + p2.X) / 2, (p1.Y + p2.Y) / 2);
    }
}
```

