```javascript
// Strategy interface
class TransactionStrategy {
  execute(transaction) {
    throw new Error("Strategy execute method must be implemented");
  }
}

// Concrete strategies
class DepositStrategy extends TransactionStrategy {
  execute(transaction) {
    transaction.account.balance += transaction.amount;
    console.log(`Deposit: $${transaction.amount} to account ${transaction.account.number}`);
  }
}

class WithdrawStrategy extends TransactionStrategy {
  execute(transaction) {
    if (transaction.account.balance >= transaction.amount) {
      transaction.account.balance -= transaction.amount;
      console.log(`Withdraw: $${transaction.amount} from account ${transaction.account.number}`);
    } else {
      console.log("Insufficient funds for withdrawal.");
    }
  }
}

class TransferStrategy extends TransactionStrategy {
  execute(transaction) {
    if (transaction.fromAccount.balance >= transaction.amount) {
      transaction.fromAccount.balance -= transaction.amount;
      transaction.toAccount.balance += transaction.amount;
      console.log(`Transfer: $${transaction.amount} from account ${transaction.fromAccount.number} to account ${transaction.toAccount.number}`);
    } else {
      console.log("Insufficient funds for transfer.");
    }
  }
}

// Context
class BankAccount {
  constructor(number, balance) {
    this.number = number;
    this.balance = balance;
  }

  performTransaction(strategy, transaction) {
    strategy.execute(transaction);
  }
}

// Usage
const account1 = new BankAccount('123', 1000);
const account2 = new BankAccount('456', 500);

const deposit = { account: account1, amount: 200 };
const withdraw = { account: account1, amount: 150 };
const transfer = { fromAccount: account1, toAccount: account2, amount: 100 };

account1.performTransaction(new DepositStrategy(), deposit);
account1.performTransaction(new WithdrawStrategy(), withdraw);
account1.performTransaction(new TransferStrategy(), transfer);
```

