  execute(account, rate) {
    const interest = account.balance * rate;
    account.balance += interest;
    console.log(`Interest: Account balance is now ${account.balance}`);
  }
}

// Context class
class BankAccount {
  constructor(balance) {
    this.balance = balance;
    this.transactionStrategy = null;
  }

  setTransactionStrategy(strategy) {
    this.transactionStrategy = strategy;
  }

  performTransaction(amount) {
    if (!this.transactionStrategy) {
      throw new Error("No transaction strategy set");
    }
    this.transactionStrategy.execute(this, amount);
  }
}

