myAccount.setTransactionStrategy(new DepositStrategy());
myAccount.performTransaction(500); // Deposit: Account balance is now 1500

myAccount.setTransactionStrategy(new WithdrawStrategy());
myAccount.performTransaction(200); // Withdraw: Account balance is now 1300

myAccount.setTransactionStrategy(new InterestStrategy());
myAccount.performTransaction(0.05); // Interest: Account balance is now 1365
